def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--cohort-id',required=True,type=int)
    parser.add_argument('--year',required=True,type=int)
    parser.add_argument('--apply',action='store_true')
    args=parser.parse_args()
    from db import SessionLocal
    from models import AcceleratorCohort, AcceleratorEvent, AcceleratorEventChange
    with SessionLocal() as db:
        cohort=db.get(AcceleratorCohort,args.cohort_id)
        if not cohort: raise SystemExit('Поток не найден')
        tz=ZoneInfo(cohort.timezone)
        events=db.query(AcceleratorEvent).filter_by(cohort_id=cohort.id).all()
        for day,title,start,end,speaker,meeting,description in ANNOUNCEMENTS:
            matches=[e for e in events if e.title==title and e.starts_at.replace(tzinfo=timezone.utc).astimezone(tz).date()==datetime(args.year,11,day).date()]
            if len(matches)!=1: raise SystemExit(f'Неоднозначное соответствие: {day} ноября, {title}; изменения отменены')
            e=matches[0]
            fields=['description','host_name','starts_at','ends_at','event_format','event_type','meeting_url','online_platform','location','post_materials']
            def snapshot():
                return {k:(getattr(e,k).isoformat() if isinstance(getattr(e,k),datetime) else getattr(e,k)) for k in fields}
            before=snapshot()
            e.description=description
            e.host_name=speaker
            e.starts_at=datetime.fromisoformat(f'{args.year}-11-{day:02d}T{start}').replace(tzinfo=tz).astimezone(timezone.utc).replace(tzinfo=None)
            e.ends_at=datetime.fromisoformat(f'{args.year}-11-{day:02d}T{end}').replace(tzinfo=tz).astimezone(timezone.utc).replace(tzinfo=None)
            e.event_format='offline' if day==16 else 'online'
            e.event_type='networking' if day==16 else 'webinar'
            e.meeting_url=f'https://my.mts-link.ru/j/152085126/{meeting}' if meeting else None
            e.online_platform='МТС Линк' if meeting else None
            if day==16:
                e.location='Техноковоркинг, брифинг-зона'
                registration={'title':'Обязательная регистрация','url':'https://opros.mirea.ru/votes/vote6af46e2ff28a7/'}
                e.post_materials=[link for link in (e.post_materials or []) if link.get('url')!=registration['url']]+[registration]
            after=snapshot()
            if before!=after:
                db.add(AcceleratorEventChange(event_id=e.id,action='updated',reason='Уточнение программы по объявлениям организатора',before=before,after=after))
            print(e.id,title,f'{day:02d}.11 {start}–{end}',e.event_format,e.meeting_url or e.location)
        if args.apply: db.commit(); print('Сохранено')
        else: db.rollback(); print('Предпросмотр. Для сохранения добавьте --apply.')

if __name__=='__main__': main()
